	CONSTRAINT "scenario_revision_money_pkey" PRIMARY KEY("organization_id","revision_id"),
	CONSTRAINT "scenario_revision_money_restricted_part_check" CHECK (jsonb_typeof(restricted_part) = 'object')
);
